function accountSettingsHTML(){
 if(!me)return '';return `<section class="surface account-settings"><h2>계정 설정</h2><label class="form-field">이메일 · 확인용<input type="email" value="${esc(me.email?.endsWith('.invalid')?'':me.email||'')}" readonly autocomplete="email" aria-label="이메일 · 확인용"></label><p class="field-help">이메일은 이 화면에서 변경할 수 없어요.</p><form id="account-nickname-form"><label class="form-field">아이디 · 활동명<input name="name" value="${esc(me.name)}" required maxlength="60" autocomplete="nickname" aria-describedby="nickname-status"></label><div class="inline-actions"><button type="button" class="small-button" data-check-nickname>중복 확인</button><button type="submit" class="primary-button">아이디 저장</button></div><p id="nickname-status" class="field-help" role="status"></p><p class="form-error" role="alert"></p></form>${me.provider==='email'?`<details class="account-password"><summary>비밀번호 변경</summary><form id="account-password-form">${formField('현재 비밀번호','current_password','password','','required maxlength="128" autocomplete="current-password"')}${formField('새 비밀번호','new_password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')}${formField('새 비밀번호 확인','confirm_password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="field-help">12자 이상으로 설정해주세요. 변경하면 다른 기기의 로그인은 해제돼요.</p><button type="submit" class="primary-button">비밀번호 저장</button><p class="form-error" role="alert"></p></form></details>`:'<p class="field-help">소셜 로그인 계정의 비밀번호는 Google·카카오·Apple에서 변경해주세요.</p>'}</section>`;
}
function bindAccountSettings(){
 const nicknameForm=$('#account-nickname-form');if(!nicknameForm)return;
 const input=nicknameForm.elements.name,status=$('#nickname-status'),check=nicknameForm.querySelector('[data-check-nickname]');let revision=0;
 input.oninput=()=>{revision++;status.textContent='';};
 check.onclick=async()=>{const value=input.value,serial=++revision;check.disabled=true;status.textContent='확인 중…';try{const out=await api('/api/account/nickname?name='+encodeURIComponent(value));if(serial===revision)status.textContent=out.available?'사용할 수 있는 아이디입니다.':out.message;}catch(e){if(serial===revision)status.textContent=e.message;}finally{check.disabled=false;}};
 nicknameForm.onsubmit=busyForm(nicknameForm,async fd=>{const out=await api('/api/account/nickname','PUT',{name:fd.get('name')});me=out.user;updateAccount();await render();toast('아이디를 변경했습니다.');});
 const passwordForm=$('#account-password-form');if(passwordForm)passwordForm.onsubmit=busyForm(passwordForm,async fd=>{if(fd.get('new_password')!==fd.get('confirm_password'))throw new Error('새 비밀번호 확인이 일치하지 않습니다.');await api('/api/account/password','PUT',{current_password:fd.get('current_password'),new_password:fd.get('new_password')});passwordForm.reset();passwordForm.closest('details').open=false;toast('비밀번호를 변경했습니다. 다른 기기는 다시 로그인해주세요.');});
}
